import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import {useContext} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {emptyArray} from '../../../../../../../../utils/empty'
import {extractFilePaths} from '../../../../../../../../utils/fileUtils'
import {DisabledContext} from '../../../../../contexts/DisabledContext'
import {usePipelineId} from '../../../../../hooks/pipeline'

import {jobDependencySelectItems} from './JobDependency.consts'

import {
  getDraftJobs,
  getJobName,
  getPipeline,
} from 'src/components/pages/PipelinesPages/EditPipelinePage/EditPipelinePage.selectors'
import {
  hoveredJob,
  pipelineDraft,
} from 'src/components/pages/PipelinesPages/EditPipelinePage/slices/EditPipelinePage.slices'

export function useDependencyFilesPublication(jobId: string) {
  const pipelineId = usePipelineId()
  const filesPublication = useAppSelector(
    state => getDraftJobs(state, pipelineId)?.[jobId]?.['files-publication'] ?? emptyArray,
  )
  const deletedFilesPublication = useAppSelector(
    state => getPipeline(state, pipelineId)?.deleted?.filesPublication,
    shallowEqual,
  )

  return filesPublication.filter(
    (_, index) => !deletedFilesPublication?.includes(`${jobId}_${index}`),
  )
}

export function useArtifactDependencies(jobId: string, dependencyId: string) {
  const pipelineId = usePipelineId()
  return useAppSelector(state => {
    const dependencies = getDraftJobs(state, pipelineId)?.[jobId]?.dependencies ?? []
    for (const dependency of dependencies) {
      if (typeof dependency === 'object' && dependencyId in dependency) {
        return dependency[dependencyId].files ?? emptyArray
      }
    }
    return emptyArray
  })
}

function useJobDependency(jobId: string, dependencyId: string) {
  const dispatch = useAppDispatch()
  const [allFiles, notUseFiles] = jobDependencySelectItems
  const pipelineId = usePipelineId()
  const dependencyFilesPublication = useDependencyFilesPublication(dependencyId)
  const handlerJobDependencySelect = (value: SelectItem | null) => {
    const {key} = value || {}
    const isAddAllFiles = key === allFiles.key
    const files = isAddAllFiles ? extractFilePaths(dependencyFilesPublication) : []

    dispatch(
      pipelineDraft.actions.setFilesDependencies({
        id: pipelineId,
        jobId,
        dependencyId,
        files,
      }),
    )
  }
  const isJobDependencyDisabled = useContext(DisabledContext)
  const handlerJobDependencyMouseHover = (id: string | null) => () =>
    dispatch(hoveredJob.actions.set(id))
  const dependencyName =
    useAppSelector(state => getJobName(state, pipelineId, dependencyId)) ?? 'Unnamed job'
  const artifactDependencies = useArtifactDependencies(jobId, dependencyId)
  const hasDependencyFilesPublication = Boolean(dependencyFilesPublication.length)
  const hasArtifactDependencies = Boolean(artifactDependencies.length)
  const selectedJobDependencyItem = hasArtifactDependencies ? allFiles : notUseFiles

  return {
    dependencyName,
    hasDependencyFilesPublication,
    selectedJobDependencyItem,
    artifactDependencies,
    isJobDependencyDisabled,
    handlerJobDependencySelect,
    handlerJobDependencyMouseHover,
  }
}

export default useJobDependency
