import {interpolateLinear} from '@jetbrains/ring-ui-built/components/global/linear-function'
import classNames from 'classnames'
import type {GraphNode as DagNode} from 'd3-dag/dist/graph'
import uniqBy from 'lodash/uniqBy'
import type {ReactNode, Ref} from 'react'
import {Fragment, useState, useMemo} from 'react'

import type {GraphNode} from '../../utils/graph'
import {createLayout} from '../../utils/graph'

import EditEdgePopup from './EditEdgePopup/EditEdgePopup'

import styles from './PipelineChart.module.css'

const EDGES_PADDING = 24
const VERTICAL_CURVE = 16

type ExtraNode<T> = {
  x: number
  y: number
  data?: GraphNode<T>
}

export type ExtraEdge<T = unknown> = {
  source: ExtraNode<T>
  target: ExtraNode<T>
  points: [number, number][]
  selected: boolean
  warning: boolean
}

type Props<T> = {
  className?: string
  graph: Record<string, GraphNode<T>>
  nodeWidth: number
  nodeHeight: number
  gapHorizontal: number
  gapVertical: number
  renderJob: (data: DagNode<GraphNode<T>>) => ReactNode
  containerRef?: Ref<HTMLDivElement>
  getExtraEdges?: (nodes: DagNode<GraphNode<T>>[]) => ExtraEdge<T>[]
  selectableEdges?: boolean
  selectedEdge?: string | null
  setSelectedEdge?: (edge: string | null) => void
  showTransitiveEdges?: boolean
}
function PipelineChart<T>({
  className,
  graph,
  nodeWidth,
  nodeHeight,
  gapHorizontal,
  gapVertical,
  renderJob,
  containerRef,
  getExtraEdges,
  selectableEdges,
  selectedEdge,
  setSelectedEdge,
  showTransitiveEdges,
}: Props<T>) {
  const {width, height, dag} = useMemo(
    () =>
      createLayout(
        graph,
        [nodeHeight + gapVertical, nodeWidth + gapHorizontal],
        showTransitiveEdges,
      ),
    [gapHorizontal, gapVertical, graph, nodeHeight, nodeWidth, showTransitiveEdges],
  )
  const nodes = useMemo(() => Array.from(dag?.nodes() ?? []), [dag])
  const edges = useMemo(
    () => [...(dag?.links() ?? []), ...(getExtraEdges?.(nodes) ?? [])],
    [dag, nodes, getExtraEdges],
  )
  const edgeOrder = useMemo(
    () =>
      Object.fromEntries(
        nodes.map(node => [
          node.data.id,
          {
            in: uniqBy(
              edges.filter(({target}) => target.data?.id === node.data.id),
              ({source}) => source.data?.id,
            )
              .sort((a, b) => a.points[a.points.length - 2][0] - b.points[b.points.length - 2][0])
              .map(({source}) => source),
            out: uniqBy(
              edges.filter(({source}) => source.data?.id === node.data.id),
              ({target}) => target.data?.id,
            )
              .sort((a, b) => a.points[1][0] - b.points[1][0])
              .map(({target}) => target),
          },
        ]),
      ),
    [edges, nodes],
  )
  const [deleteButtonHovered, setDeleteButtonHovered] = useState(false)

  return useMemo(
    () => (
      <div
        className={classNames(styles.wrapper, className)}
        style={{width: height - EDGES_PADDING, height: width}}
        ref={containerRef}
      >
        {nodes.map(renderJob)}
        <svg
          height={width + 2 * EDGES_PADDING}
          width={height + 2 * EDGES_PADDING}
          className={styles.edges}
        >
          {edges.map(edge => {
            const sourceId = edge.source.data?.id
            const targetId = edge.target.data?.id
            const sourceOrder = sourceId != null ? edgeOrder[sourceId]?.out : null
            const sourceOffsetY =
              sourceOrder != null
                ? (nodeHeight * (sourceOrder.indexOf(edge.target) + 1)) / (sourceOrder.length + 1)
                : nodeHeight / 2
            const targetOrder = targetId != null ? edgeOrder[targetId]?.in : null
            const targetOffsetY =
              targetOrder != null
                ? (nodeHeight * (targetOrder.indexOf(edge.source) + 1)) / (targetOrder.length + 1)
                : nodeHeight / 2
            const points = edge.points.map(([x, y], i, array) => {
              const phase = i / (array.length - 1)
              return {
                x:
                  y! +
                  EDGES_PADDING +
                  interpolateLinear(
                    nodeWidth / 2 - gapHorizontal / 2,
                    -nodeWidth / 2 - gapHorizontal / 2,
                    phase,
                  ),
                y:
                  x! +
                  EDGES_PADDING -
                  nodeHeight / 2 -
                  gapVertical / 2 +
                  interpolateLinear(sourceOffsetY, targetOffsetY, phase),
              }
            })
            const d = `M ${points[0].x} ${points[0].y} ${points
              .slice(1)
              .map((point, i) => {
                const prevPoint = points[i]
                const halfXDistance = Math.abs(point.x - prevPoint.x) / 2
                const verticalCurveOffset =
                  point.x < prevPoint.x && Math.abs(point.y - prevPoint.y) < VERTICAL_CURVE
                    ? VERTICAL_CURVE
                    : 0
                return `C ${prevPoint.x + halfXDistance} ${prevPoint.y - verticalCurveOffset}, ${point.x - halfXDistance} ${point.y - verticalCurveOffset}, ${point.x} ${point.y}`
              })
              .join(' ')}`
            const id = `${sourceId} => ${targetId}`
            const isSelectedEdge = selectedEdge === id
            const middle =
              points.length % 2 === 0
                ? {
                    x: (points[points.length / 2 - 1].x + points[points.length / 2].x) / 2,
                    y: (points[points.length / 2 - 1].y + points[points.length / 2].y) / 2,
                  }
                : points[(points.length - 1) / 2]
            return (
              <Fragment key={id}>
                {selectableEdges && (
                  <path
                    data-edge-hover-area="true"
                    className={styles.hoverArea}
                    d={d}
                    onClick={() => setSelectedEdge?.(isSelectedEdge ? null : id)}
                  />
                )}
                <path
                  className={classNames({
                    [styles.selected]: isSelectedEdge || ('selected' in edge && edge.selected),
                    [styles.warning]: 'warning' in edge && edge.warning,
                    [styles.deleting]: isSelectedEdge && deleteButtonHovered,
                    [styles.transitive]:
                      targetId != null &&
                      sourceId != null &&
                      !graph[targetId].optimizedDependencies.has(sourceId) &&
                      graph[targetId].predecessors.has(sourceId),
                  })}
                  d={d}
                />
                {isSelectedEdge && sourceId != null && targetId != null && (
                  <rect stroke="transparent" x={middle.x - 1} y={middle.y - 1} width={2} height={2}>
                    <EditEdgePopup
                      sourceId={sourceId}
                      targetId={targetId}
                      setDeleteButtonHovered={setDeleteButtonHovered}
                      setSelectedEdge={setSelectedEdge}
                    />
                  </rect>
                )}
              </Fragment>
            )
          })}
        </svg>
      </div>
    ),
    [
      className,
      containerRef,
      deleteButtonHovered,
      edgeOrder,
      edges,
      gapHorizontal,
      gapVertical,
      graph,
      height,
      nodeHeight,
      nodeWidth,
      nodes,
      renderJob,
      selectableEdges,
      selectedEdge,
      setSelectedEdge,
      width,
    ],
  )
}

export default PipelineChart
