import {useCallback} from 'react'

import {useAppDispatch, useAppStore} from '../../../../../../../hooks/react-redux'
import {extractFilePaths} from '../../../../../../../utils/fileUtils'
import {usePipelineId} from '../../../../hooks/pipeline'
import {
  useNonDeletedPipelineJobIdsOrDraft,
  usePipelineDraftGraph,
} from '../../../EditPipelinePage.hooks'
import {getDraftJobs} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'

export function useDependencies(jobId: string) {
  const jobs = useNonDeletedPipelineJobIdsOrDraft()
  const graph = usePipelineDraftGraph()
  const {predecessors, successors, dependencies, dependants} = graph[jobId] ?? {
    dependencies: new Set(),
    dependants: new Set(),
    predecessors: new Set(),
    successors: new Set(),
  }
  return {
    dependencies,
    dependants,
    possibleDependencies: jobs.filter(id => id !== jobId && !successors.has(id)),
    possibleDependants: jobs.filter(id => id !== jobId && !predecessors.has(id)),
  }
}

export function useToggleDependency() {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const graph = usePipelineDraftGraph()
  const {getState} = useAppStore()
  return useCallback(
    (jobId: string, dependencyId: string, on: boolean) => {
      const {dependencies = []} = graph[jobId] ?? {}
      dispatch(
        pipelineDraft.actions.setDependencies({
          id: pipelineId,
          jobId,
          dependencies: on
            ? [...dependencies, dependencyId]
            : [...dependencies].filter(otherId => otherId !== dependencyId),
        }),
      )

      // Task: TCP-22 Rework "Use files..." link on Dependencies block
      // Auto Assign publication files from the dependent job
      const pipelineJobs = getDraftJobs(getState(), pipelineId)
      const files = pipelineJobs?.[dependencyId]?.['files-publication']
        ? extractFilePaths(pipelineJobs[dependencyId]['files-publication'])
        : []
      if (on && files.length) {
        dispatch(
          pipelineDraft.actions.setFilesDependencies({
            id: pipelineId,
            jobId,
            dependencyId,
            files,
          }),
        )
      }
    },
    [dispatch, pipelineId, graph, getState],
  )
}
