import Theme, {WithThemeClasses} from '@jetbrains/ring-ui-built/components/global/theme'
import Shortcuts from '@jetbrains/ring-ui-built/components/shortcuts/shortcuts'
import Toggle, {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useId} from 'react'

import {useAppDispatch} from '../../../../../../hooks/react-redux'
import {extractFilePaths} from '../../../../../../utils/fileUtils'
import Popup from '../../../../../common/Popup/Popup'
import {useToggleDependency} from '../../../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobDependencies/JobDependencies.hooks'
import {
  useArtifactDependencies,
  useDependencyFilesPublication,
} from '../../../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobDependencies/JobDependency/JobDependency.hooks'
import {pipelineDraft} from '../../../EditPipelinePage/slices/EditPipelinePage.slices'
import {usePipelineId} from '../../../hooks/pipeline'

import styles from './EditEdgePopup.module.css'

type Props = {
  sourceId: string
  targetId: string
  setSelectedEdge?: (edge: string | null) => void
  setDeleteButtonHovered: (hovered: boolean) => void
}

export default function EditEdgePopup({
  sourceId,
  targetId,
  setSelectedEdge,
  setDeleteButtonHovered,
}: Props) {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const files = extractFilePaths(useDependencyFilesPublication(sourceId))
  const artifactDependencies = useArtifactDependencies(targetId, sourceId)
  const toggleDependency = useToggleDependency()
  const scope = useId()
  const deleteLine = () => {
    toggleDependency(targetId, sourceId, false)
    setSelectedEdge?.(null)
    setDeleteButtonHovered(false)
  }

  return (
    <Shortcuts scope={scope} map={{backspace: deleteLine}}>
      <WithThemeClasses theme={Theme.DARK}>
        {themeClasses => (
          <Popup
            className={classNames(styles.popup, themeClasses)}
            offset={8}
            directions={[Popup.PopupProps.Directions.TOP_CENTER]}
            onCloseAttempt={e => {
              if (
                !(e?.target instanceof Element) ||
                e.target.closest('[data-edge-hover-area]') == null
              ) {
                setSelectedEdge?.(null)
                setDeleteButtonHovered(false)
              }
            }}
          >
            {Boolean(files?.length) && (
              <Toggle
                size={Size.Size14}
                className={styles.useArtifacts}
                checked={artifactDependencies.length > 0}
                onChange={e => {
                  dispatch(
                    pipelineDraft.actions.setFilesDependencies({
                      id: pipelineId,
                      jobId: targetId,
                      dependencyId: sourceId,
                      files: e.target.checked ? files : [],
                    }),
                  )
                }}
              >
                {'Use shared files'}
              </Toggle>
            )}
            <IconButton
              className={styles.deleteLine}
              icon={'trash'}
              danger
              title=""
              aria-label="Delete line"
              onMouseEnter={() => setDeleteButtonHovered(true)}
              onMouseLeave={() => setDeleteButtonHovered(false)}
              onClick={deleteLine}
            />
          </Popup>
        )}
      </WithThemeClasses>
    </Shortcuts>
  )
}
